import numpy as np
def _ring(length):
    h = np.zeros((length, length), dtype=int)
    for i in range(length):
        h[i, i] = 1
        h[i, (i + 1) % length] = 1
    return h
def _sig(a, salt):
    a = np.asarray(a, dtype=float)
    k = np.arange(a.size, dtype=float)
    return (1000.0 * a.shape[0] + a.shape[1] + np.abs(a).sum()
            + float(a.ravel() @ np.cos(salt * k + 0.3)))
def _pair(out):
    d, hz = out
    return _sig(d, 0.7) + 0.5 * _sig(hz, 1.3)
assert np.allclose(build_phenomenological_check_matrix(_ring(3), _ring(4)), target)

